using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.VertexAlgebra.Lattice.PhysicalLie;

internal sealed class LatticeBRSTPerturbationFiltrationDocument : IScribeDocumentDefinition
{
    private static DocumentBlock Node(string name, string title, string prose, DescribeRole role) => Describe.Lean(
        DescribeId.Create("latticebrstperturbationfiltration-" + name.Replace("_", "-").ToLowerInvariant()),
        DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTPerturbationFiltration." + name), H(title), StatementSource.WithoutFormula(),
        AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))), role);
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Fixed energy and signed filtration for the original lattice BRST charge",
        H("Fixed energy and signed filtration for the original lattice BRST charge"), Blocks(
            Paragraph(Text("The carrier is the actual State D, the all-charge lattice matter carrier tensored with the original countable bc occupation Fock space. D and its rank, null frame F, transverse dimension t and basis B retain their original quantifiers. H has both inverse-Gram hypotheses wherever the source requires them. Charge beta is integral; level and filtration lower are arbitrary integers. Q is the original LatticeBRST.totalCharge D H, and all basis statements use the original actualBasis F B.")),
            Paragraph(Text("The signed degree bounds retain both exceptional ghost zero-mode occupations. The sector restrictions concern the original BRST charge and do not assert a physical no-ghost theorem.")),
            Node("groundEnergy", "Charge ground energy", "For every lattice D and integral charge beta, groundEnergy beta is bilinear D beta beta, cast to C, divided by 2.", DescribeRole.Definition),
            Node("totalL0", "Actual total zero mode", "For every D and matrix H of size Fin D.rank, totalL0 H is the original matter mode at 0 plus the original ghost Virasoro mode at 0, on the full State D.", DescribeRole.Definition),
            Node("oscillatorLevel", "Oscillator frequency level", "For every transverse dimension t and exponent vector m, oscillatorLevel m is Finsupp.weight frequencyWeight m.", DescribeRole.Definition),
            Node("indexLevel", "Integer level of every raw occupation", "For every StateIndex D t, indexLevel is oscillatorLevel plus BcGhostRelativeEnergy.relativeEnergy of the raw ghost occupation. No occupation is discarded.", DescribeRole.Definition),
            Node("degree_bounds", "Full signed degree window", "For every D, t and raw index i, -indexLevel i <= degree i and degree i <= indexLevel i + 1. The original degree is exponentDegree plus ghost charge minus 1. Both occupations {1} and {1,3} remain.", DescribeRole.Theorem),
            Node("totalL0_basis", "Energy of the actual basis", "For every D, null frame F, transverse basis B, H satisfying both H * gramComplex D = 1 and gramComplex D * H = 1, and every i, totalL0 H applied to actualBasis F B i equals (groundEnergy i.1.1 + (indexLevel i : C) - 1) times that same basis vector.", DescribeRole.Theorem),
            Node("totalL0_diagonal", "Diagonal form on the actual basis", "For the same arbitrary D, F, B and H with both inverse-Gram identities, totalL0 H is diagonal on actualBasis F B with eigenvalue groundEnergy i.1.1 + (indexLevel i : C) - 1.", DescribeRole.Theorem),
            Node("fixedSector", "Literal fixed charge and total energy", "For every D, H, integral charge beta and integer level, fixedSector H beta level is the submodule of the full State D defined by chargeProject beta v = v and totalL0 H v = (groundEnergy beta + (level : C) - 1) times v. There is no global energy cutoff.", DescribeRole.Definition),
            Node("mem_fixedSector_iff", "Exact coefficient characterization of the sector", "For arbitrary F and B and both inverse-Gram identities for H, v belongs to fixedSector H beta level if and only if every nonzero actualBasis coefficient has charge beta and indexLevel equal to level. All integer levels remain quantified.", DescribeRole.Theorem),
            Node("basis_mem_fixedSector", "Each basis vector lies in its own sector", "For every raw index i and both inverse-Gram identities, actualBasis F B i belongs to fixedSector H i.1.1 (indexLevel i).", DescribeRole.Theorem),
            Node("signedFiltration", "Original signed filtration", "For arbitrary beta and integers level and lower, signedFiltration F B beta level lower is the C-span of the actual basis vectors with charge beta, indexLevel equal to level and lower <= degree. It is a submodule of the original State D.", DescribeRole.Definition),
            Node("mem_signedFiltration_iff", "Exact coefficient characterization of the filtration", "For every beta, integer level and lower, and v in the full State D, filtration membership is equivalent to every nonzero actualBasis coefficient satisfying exactly charge beta, indexLevel equal to level and lower <= degree.", DescribeRole.Theorem),
            Node("sector_mem_filtration", "Lower endpoint for every sector vector", "With both inverse-Gram identities, every v in fixedSector H beta level belongs to signedFiltration F B beta level (-level), for every integral beta and integer level.", DescribeRole.Theorem),
            Node("filtration_exhausted", "Exhaustion above the actual upper endpoint", "For every beta and integers level and lower with level + 1 < lower, signedFiltration F B beta level lower is bottom. No positivity or critical-rank assumption is added.", DescribeRole.Theorem),
            Node("totalL0_Q", "Original Q commutes with total energy", "For every rank and H satisfying both inverse-Gram identities, totalL0 H commutes with the original LatticeBRST.totalCharge D H. This is the existing covariance at mode zero, where its anomaly vanishes in every rank.", DescribeRole.Theorem),
            Node("Q_preserves", "Original Q preserves the literal sector", "For every F, B, H satisfying both inverse-Gram identities, integral beta, integer level and v in fixedSector H beta level, the original LatticeBRST.totalCharge D H v remains in that same sector.", DescribeRole.Theorem),
            Node("totalL0_d0", "The leading differential commutes with total energy", "For every null frame F, H satisfying both inverse-Gram identities and integral beta, totalL0 H commutes with the existing d0 F beta. The paired current and ghost mode indices range over all integers.", DescribeRole.Theorem),
            Node("totalL0_h", "The existing homotopy commutes with total energy", "For every F, B, H satisfying both inverse-Gram identities and integral beta, totalL0 H commutes with the original h F B beta.", DescribeRole.Theorem),
            Node("d0_preserves", "The leading differential preserves the literal sector", "For every F, B, H satisfying both inverse-Gram identities, beta, integer level and sector vector v, d0 F beta v remains in fixedSector H beta level.", DescribeRole.Theorem),
            Node("h_preserves", "The homotopy preserves the literal sector", "For every F, B, H satisfying both inverse-Gram identities, beta, integer level and sector vector v, h F B beta v remains in fixedSector H beta level.", DescribeRole.Theorem),
            Node("P0_preserves", "The actual zero-count projector preserves the sector", "For every F, B, H satisfying both inverse-Gram identities, beta, integer level and sector vector v, P0 F B v remains in fixedSector H beta level. Both exceptional ghost zero-mode occupations remain available.", DescribeRole.Theorem),
            Paragraph(Text("Finite homological transfer uses the sector restrictions and filtration bounds. Its critical-rank hypothesis belongs to that construction; the fixed-energy filtration itself retains arbitrary rank.")))));
}
